import{_ as i,o as h,c as t,a5 as a}from"./chunks/framework.CsGesDJn.js";const k=JSON.parse('{"title":"Tính năng riêng cho mobile và làm đẹp giao diện","description":"","frontmatter":{},"headers":[],"relativePath":"feature/mobile-native-enhancements/spec.md","filePath":"feature/mobile-native-enhancements/spec.md"}'),e={name:"feature/mobile-native-enhancements/spec.md"};function o(c,n,g,l,r,s){return h(),t("div",null,[...n[0]||(n[0]=[a('<h1 id="tinh-nang-rieng-cho-mobile-va-lam-đep-giao-dien" tabindex="-1">Tính năng riêng cho mobile và làm đẹp giao diện <a class="header-anchor" href="#tinh-nang-rieng-cho-mobile-va-lam-đep-giao-dien" aria-label="Permalink to &quot;Tính năng riêng cho mobile và làm đẹp giao diện&quot;">​</a></h1><p>Viết sau khi code, vì yêu cầu đến khi chủ dự án vắng mặt (2026-11-04). Cần được rà lại theo đúng quy trình <code>spec → plan → task → test</code>.</p><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Dùng những gì chỉ điện thoại có để giúp người dùng: bảo vệ dữ liệu trên máy, nhắc việc không cần backend, báo rõ khi mất mạng, phản hồi xúc giác. Dashboard chỉ vẽ dữ liệu thật.</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>Là người dùng, tôi muốn khoá app bằng vân tay, khuôn mặt hoặc mật khẩu máy, để người mượn điện thoại không xem được dữ liệu khách hàng.</li><li>Là Creator, tôi muốn được nhắc trước hạn Task, để không trễ deadline dù không mở app.</li><li>Là người quay video ngoài hiện trường, tôi muốn biết khi mất mạng, và biết video đã quay vẫn được giữ.</li><li>Là Manager, tôi muốn thấy số liệu thật của Workspace trên Dashboard.</li></ul><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><p><strong>Khoá ứng dụng</strong></p><ul><li>AC-L1: Bật trong Cài đặt ứng dụng. Phải xác minh thành công mới đổi được trạng thái, cả khi bật lẫn khi tắt.</li><li>AC-L2: Máy chưa đặt khoá màn hình thì không bật được, và có thông báo.</li><li>AC-L3: Khi đã bật: khoá lúc mở app và khi quay lại sau từ 60 giây ở nền. Đồng hồ máy bị chỉnh lùi cũng khoá.</li><li>AC-L4: Huỷ hoặc xác minh sai thì vẫn khoá, có nút thử lại.</li><li>AC-L5: Luôn có nút Đăng xuất, để không ai bị kẹt.</li><li>AC-L6: Khi khoá, nút Back không điều khiển màn phía sau, trình đọc màn hình không đọc nội dung phía sau.</li><li>AC-L7: Mở khoá xong vẫn ở đúng màn cũ, bản nháp và upload không mất.</li></ul><p><strong>Nhắc hạn Task</strong></p><ul><li>AC-R1: Tắt mặc định. Bật thì xin quyền thông báo; bị từ chối thì không bật và có đường mở Cài đặt máy.</li><li>AC-R2: Nhắc trước 1 ngày và 1 giờ với Task đang mở được giao cho người đang đăng nhập, trong Workspace hiện tại.</li><li>AC-R3: Bỏ qua mốc đã qua và Task không có hạn hoặc hạn sai định dạng. Tối đa 40 lịch, ưu tiên gần nhất (iOS giới hạn 64).</li><li>AC-R4: Lịch được thay mới khi mở app. Task đã xong hoặc đổi người thì không còn nhắc.</li><li>AC-R5: Tắt tính năng hoặc đăng xuất thì huỷ mọi lịch nhắc, để tài khoản khác trên máy không nhận.</li><li>AC-R6: Chạm thông báo mở đúng Task, đổi Workspace nếu cần. Mất quyền vào Workspace thì không làm gì.</li></ul><p><strong>Báo mất mạng</strong></p><ul><li>AC-O1: Không có kết nối thì hiện dòng báo ở trên cùng, không chặn thao tác, tự ẩn khi có mạng lại.</li></ul><p><strong>Phản hồi xúc giác</strong></p><ul><li>AC-H1: Nhẹ khi bấm nút. Thành công hoặc cảnh báo cho thao tác Task, Kanban, gửi email. Máy không hỗ trợ thì bỏ qua, không lỗi.</li></ul><p><strong>Dashboard</strong></p><ul><li>AC-D1: Bỏ biểu đồ dữ liệu mẫu. Biểu đồ Task theo trạng thái và Task đến hạn 6 tháng tính từ Task thật, không tính Task đã huỷ.</li><li>AC-D2: Role không được xem danh sách Task của Workspace thì không hiện khu biểu đồ. Không có Task thì hiện câu báo, không vẽ biểu đồ rỗng.</li><li>AC-D3: Thẻ chào hiện số Task đang mở và số sắp đến hạn trong 3 ngày, tính cả quá hạn.</li></ul><p><strong>Đa ngôn ngữ và giao diện</strong></p><ul><li>AC-I1: Mọi chuỗi mới có trong <code>src/i18n/locales/en.json</code>, khoá là câu tiếng Việt qua <code>tr()</code>.</li><li>AC-T1: Màu dùng token theo theme. Riêng <code>brandGradient</code> giữ nguyên ở 2 theme, chữ trên đó luôn màu trắng.</li></ul><h2 id="_4-api" tabindex="-1">4. API <a class="header-anchor" href="#_4-api" aria-label="Permalink to &quot;4. API&quot;">​</a></h2><p>Không thêm API. Nhắc hạn dùng <code>GET /api/v1/workspaces/{id}/tasks</code> sẵn có.</p><h2 id="_5-out-of-scope" tabindex="-1">5. Out of Scope <a class="header-anchor" href="#_5-out-of-scope" aria-label="Permalink to &quot;5. Out of Scope&quot;">​</a></h2><p>Push notification từ server, khoá theo từng Workspace, nhắc cho Workspace không chọn hiện tại.</p><h2 id="_6-đinh-nghia-hoan-thanh" tabindex="-1">6. Định nghĩa hoàn thành <a class="header-anchor" href="#_6-đinh-nghia-hoan-thanh" aria-label="Permalink to &quot;6. Định nghĩa hoàn thành&quot;">​</a></h2><p>Toàn bộ AC ở <code>test.md</code> đạt trên Android và iOS. Hiện chưa kiểm tra trên iOS và thiết bị thật, xem <code>test.md</code>.</p>',25)])])}const m=i(e,[["render",o]]);export{k as __pageData,m as default};
